/**  Within 0.2° of level. */
"level" | 
/**  Levelled by the suggestion's angle. */
"rotate" | 
/**  No horizon or verticals that agree, or a tilt beyond 10°. */
"unsure";

/**  Where Auto crop's subject came from. */
